import {useState,type FormEvent} from "react";
import {Input} from "./Input";import {Textarea} from "./Textarea";import {Button} from "./Button";
import styles from "./ContactForm.module.css";
export const ContactForm=()=>{const [busy,setBusy]=useState(false);const [result,setResult]=useState("");const [failed,setFailed]=useState(false);
async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();if(busy)return;const form=event.currentTarget;if(!form.reportValidity())return;setBusy(true);setResult("");setFailed(false);
try{const fields=new FormData(form);const response=await fetch("/_api/contact",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(fields))});if(!response.ok)throw Error(response.status===429?"Aguarde alguns minutos antes de enviar outra mensagem.":"Não foi possível registrar. Tente novamente.");setResult("Sua mensagem foi registrada. Obrigado pelo contato.");form.reset();}catch(e){setFailed(true);setResult(e instanceof Error?e.message:"Não foi possível registrar sua mensagem.");}finally{setBusy(false);}}
return <form className={styles.form} onSubmit={submit} aria-label="Formulário de contato">
<label>Seu nome (obrigatório)<Input name="name" autoComplete="name" required minLength={2} maxLength={150}/></label>
<label>Seu e-mail (obrigatório)<Input name="email" type="email" autoComplete="email" required maxLength={254}/></label>
<label>Assunto<Input name="subject" required minLength={2} maxLength={250}/></label>
<label>Sua mensagem<Textarea name="message" required minLength={5} maxLength={10000} rows={5}/></label>
<div className={styles.trap} aria-hidden="true"><label>Website<Input name="website" tabIndex={-1} autoComplete="off"/></label></div>
<Button type="submit" disabled={busy}>{busy?"Registrando…":"Enviar"}</Button>
{result&&<p className={failed?styles.error:styles.success} role={failed?"alert":"status"}>{result}</p>}
</form>;};

