import {schema} from "./contact_POST.schema";import {db} from "../helpers/db";
export async function handle(request:Request){try{
if(Number(request.headers.get("content-length")||0)>15000)return Response.json({ok:false},{status:413});
const origin=request.headers.get("origin");if(origin&&new URL(origin).host!==new URL(request.url).host)return Response.json({ok:false},{status:403});
const text=await request.text();if(text.length>15000)return Response.json({ok:false},{status:413});
const body=JSON.parse(text);if(body.website)return Response.json({ok:true});
const parsed=schema.safeParse(body);if(!parsed.success)return Response.json({ok:false},{status:400});
const recent=await db.selectFrom("contactMessages").select("id").where("email","=",parsed.data.email).where("createdAt",">",new Date(Date.now()-10*60*1000)).limit(3).execute();
if(recent.length>=3)return Response.json({ok:false},{status:429});
await db.insertInto("contactMessages").values(parsed.data).execute();return Response.json({ok:true});
}catch{return Response.json({ok:false},{status:500});}}
